#!/usr/bin/env python3
from __future__ import annotations
import argparse, hashlib, struct
from pathlib import Path

BASIS_SHA256="e15747f4920bd5f40db9019e4e45110ad4655b4defab1ad3027b039fc022d98b"
OUTPUT_SHA256="db2e6547b5fb5516d4ad6559173e66421315d1635ca0c08e8141b0de2f57f966"
EXPECTED_DXBC_COUNT=78
SHARED={33:"a4e5a097dcae88c7fd0897ae82c5842ef40d01b274f97d043c1937b4d28e4226",34:"1c028ba78bc934c1887bf041ecb7d884029be7744afe97a75d6fab3d52fbe496",35:"702140b61b38cd22ade40737f49de7eee8cdb4a8e849cbc156eef9bfbdbb72b2"}
PRE={72:"bf5da767361e5d3d4354de2c30b67e68029ac865fe4823c61ae6d25d273da49f",73:"4c79a8eb7b8aa744f756a04b1af968a1da105726914ed420feb7424334c31566",74:"3c0660946fa93a6c1a4b744a7fe31348ae0b62b19b1e7da3372782fd337530e9"}
POST={72:"159e9bbcb36c110e0e6e223f740986844cc8f0882d472afaf5b65abee4301e98",73:"726461e5308788f75e7dba4e0e7c85e9fcc801faec38c060635dff40fb9ae877",74:"11a405536a0600037b11817579a29cf5663bc62e8b17955af255d279e03417c7"}
PATCH={
 72:(1567,"","171721fc0e2aa01088b55fa4a9067e82"),
 73:(1476,"","38a20cacd0f11e23efb2c2c8f66b3c91"),
 74:(1136,"","02b157dfe60e24bd07f405b6d687471c"),
}

def sha(b): return hashlib.sha256(b).hexdigest()

def scan(data):
    out=[]; pos=0
    while True:
        i=data.find(b"DXBC",pos)
        if i<0: break
        if i+32<=len(data):
            size=struct.unpack_from("<I",data,i+24)[0]
            chunks=struct.unpack_from("<I",data,i+28)[0]
            if 32<=size<=200000 and i+size<=len(data) and 1<=chunks<=32:
                out.append((i,size,data[i:i+size]))
        pos=i+4
    return out

def shex_rel(blob):
    n=struct.unpack_from("<I",blob,28)[0]
    for k in range(n):
        o=struct.unpack_from("<I",blob,32+4*k)[0]
        if blob[o:o+4] in (b"SHEX",b"SHDR"):
            return o+8
    raise RuntimeError("no SHEX/SHDR")

def main():
    ap=argparse.ArgumentParser()
    ap.add_argument("basis",type=Path)
    ap.add_argument("output",type=Path)
    a=ap.parse_args()
    original=a.basis.read_bytes()
    if sha(original)!=BASIS_SHA256: raise SystemExit("refusing unknown basis")
    emb=scan(original)
    if len(emb)!=EXPECTED_DXBC_COUNT: raise SystemExit("unexpected DXBC count")
    for i,h in SHARED.items():
        if sha(emb[i][2])!=h: raise SystemExit(f"shared {i} guard mismatch")
    for i,h in PRE.items():
        if sha(emb[i][2])!=h: raise SystemExit(f"dedicated {i} guard mismatch")
    result=bytearray(original)
    for i,(word0,hexwin,hexsum) in PATCH.items():
        fileoff,size,blob=emb[i]
        rel=shex_rel(blob)
        win=bytes.fromhex(hexwin)
        if len(win)!=400: raise SystemExit("bad patch window")
        abs0=fileoff+rel+word0*4
        result[abs0:abs0+400]=win
        result[fileoff+4:fileoff+20]=bytes.fromhex(hexsum)
    final=bytes(result)
    out=scan(final)
    changed=[i for i,(x,y) in enumerate(zip(emb,out)) if x[2]!=y[2]]
    if changed!=[72,73,74]: raise SystemExit(f"unexpected changed set {changed}")
    for i,h in SHARED.items():
        if sha(out[i][2])!=h: raise SystemExit(f"shared {i} changed")
    for i,h in POST.items():
        if sha(out[i][2])!=h: raise SystemExit(f"dedicated {i} output mismatch")
    if sha(final)!=OUTPUT_SHA256: raise SystemExit(f"unexpected output {sha(final)}")
    a.output.parent.mkdir(parents=True,exist_ok=True)
    a.output.write_bytes(final)
    print("PASS",OUTPUT_SHA256)

if __name__=="__main__": main()
